import re, sys, json, subprocess, os
REPO = "/Users/guygouri/Devlab/ernlang/ern"

def strip_comments(src):
    out = []; i = 0; n = len(src); depth = 0
    while i < n:
        if src.startswith("/-", i):
            depth += 1; i += 2; continue
        if depth > 0:
            if src.startswith("-/", i):
                depth -= 1; i += 2; continue
            out.append("\n" if src[i] == "\n" else " "); i += 1; continue
        if src.startswith("--", i):
            j = src.find("\n", i)
            if j < 0: j = n
            out.append(" " * (j - i)); i = j; continue
        if src[i] == '"':
            j = i + 1
            while j < n and src[j] != '"':
                if src[j] == '\\': j += 1
                j += 1
            out.append(src[i:j+1]); i = j + 1; continue
        out.append(src[i]); i += 1
    return "".join(out)

KW = r"(theorem|lemma|def|abbrev|structure|inductive|class|instance|opaque|example)"
DECL = re.compile(r"^((?:@\[[^\]]*\]\s*)?(?:(?:private|protected|noncomputable|partial|unsafe|nonrec)\s+)*)" + KW + r"\b\s*([^\s:(\[{]*)", re.S)

def top_cut(s, kw):
    depth = 0; i = 0; n = len(s)
    while i < n:
        c = s[i]
        if c in "([{⟨": depth += 1
        elif c in ")]}⟩": depth -= 1
        elif depth == 0:
            if s.startswith(":=", i): return s[:i], s[i:]
            if kw in ("structure", "class", "inductive") and re.match(r"\bwhere\b", s[i:]) and (i == 0 or not (s[i-1].isalnum() or s[i-1] == '_')):
                return s[:i], s[i:]
            if re.match(r"\bwhere\b", s[i:]) and (i == 0 or not (s[i-1].isalnum() or s[i-1]=='_')) and kw in ("def","abbrev","instance"):
                return s[:i], s[i:]
            if c == "|" and kw in ("def", "abbrev", "inductive", "theorem", "lemma") and s[i-1] in " \n" : return s[:i], s[i:]
        i += 1
    return s, ""

def norm(s): return " ".join(s.split())

def parse(src):
    src = strip_comments(src)
    lines = src.split("\n")
    chunks = []; cur = None
    for ln in lines:
        if ln and not ln[0].isspace():
            if cur is not None: chunks.append(cur)
            cur = [ln]
        else:
            if cur is None: cur = [ln]
            else: cur.append(ln)
    if cur: chunks.append(cur)
    ns = []; res = {}
    for ch in chunks:
        text = "\n".join(ch)
        first = ch[0].strip()
        m = re.match(r"namespace\s+(\S+)", first)
        if m: ns.append(("ns", m.group(1))); continue
        m = re.match(r"section\b\s*(\S*)", first)
        if m: ns.append(("sec", m.group(1))); continue
        m = re.match(r"end\b\s*(\S*)", first)
        if m and not first.startswith("end_"):
            if ns: ns.pop()
            continue
        m = DECL.match(text)
        if not m: continue
        kw = m.group(2); name = m.group(3)
        if kw in ("instance", "example") : name = name or ("<%s@%d>" % (kw, len(res)))
        if not name or name.startswith("("): name = "<anon %s %d>" % (kw, len(res))
        prefix = ".".join(x[1] for x in ns if x[0] == "ns")
        full = (prefix + "." + name) if prefix and not name.startswith("_root_.") else name
        stmt, body = top_cut(text[m.end():], kw)
        key = full
        k = 2
        while key in res: key = full + "#%d" % k; k += 1
        res[key] = {"kw": kw, "mods": norm(m.group(1)), "stmt": norm(stmt), "body": norm(body)}
    return res

def files_at(rev):
    if rev == "WT":
        out = subprocess.run(["bash","-c","cd %s && find formal -name '*.lean' -not -path '*/.lake/*'" % REPO], capture_output=True, text=True).stdout.split()
        return {f: open(os.path.join(REPO, f)).read() for f in out}
    out = subprocess.run(["git","-C",REPO,"ls-tree","-r","--name-only",rev,"formal"], capture_output=True, text=True).stdout.split()
    out = [f for f in out if f.endswith(".lean") and "/.lake/" not in f]
    return {f: subprocess.run(["git","-C",REPO,"show","%s:%s" % (rev,f)], capture_output=True, text=True).stdout for f in out}

def collect(rev):
    d = {}
    for f, src in files_at(rev).items():
        for k, v in parse(src).items():
            v["file"] = f
            d[k] = v
    return d

if __name__ == "__main__":
    old = collect(sys.argv[1]); new = collect(sys.argv[2])
    json.dump({"old": old, "new": new}, open(sys.argv[3], "w"))
    removed = sorted(set(old) - set(new)); added = sorted(set(new) - set(old))
    changed_stmt = sorted(k for k in set(old) & set(new) if old[k]["stmt"] != new[k]["stmt"])
    changed_body_def = sorted(k for k in set(old) & set(new) if old[k]["stmt"] == new[k]["stmt"] and old[k]["body"] != new[k]["body"] and old[k]["kw"] not in ("theorem","lemma","example"))
    changed_mods = sorted(k for k in set(old) & set(new) if old[k]["mods"] != new[k]["mods"])
    print("old", len(old), "new", len(new))
    print("== REMOVED", len(removed))
    for k in removed: print("  ", old[k]["kw"], k, old[k]["file"])
    print("== ADDED", len(added))
    for k in added: print("  ", new[k]["kw"], k, new[k]["file"])
    print("== STMT CHANGED", len(changed_stmt))
    for k in changed_stmt: print("  ", old[k]["kw"], k, old[k]["file"])
    print("== DEF BODY CHANGED (same signature)", len(changed_body_def))
    for k in changed_body_def: print("  ", old[k]["kw"], k, old[k]["file"])
    print("== MODS CHANGED", changed_mods)
